 <a href="#espetinhostradicionais" class="botao-esteira">ESPETINHOS</a>
 </div>
 </div>
</div>

<script>
 const esteira = document.getElementById('esteiraAuto');
 let scrollSpeed = 0.5; // pixels por passo
 let autoScroll;
 let userIsInteracting = false;

 function startAutoScroll() {
 if (!userIsInteracting) {
 autoScroll = requestAnimationFrame(step);
 }
 }

 function step() {
 if (!userIsInteracting) {
 esteira.scrollLeft += scrollSpeed;
 const maxScroll = esteira.scrollWidth / 3;
 if (esteira.scrollLeft >= maxScroll) {
 esteira.scrollLeft = 0;
 }
 autoScroll = requestAnimationFrame(step);
 }
 }

 function stopAutoScrollTemporariamente() {
 userIsInteracting = true;
 cancelAnimationFrame(autoScroll);
 setTimeout(() => {
 userIsInteracting = false;
 startAutoScroll();
 }, 3000);
 }

 // Inicia automaticamente
 startAutoScroll();

 // Pausar ao interagir
 ['mousedown', 'touchstart', 'mouseenter'].forEach(evt =>
 esteira.addEventListener(evt, stopAutoScrollTemporariamente)
 );

 // Retomar depois da interação
 ['mouseup', 'touchend', 'mouseleave'].forEach(evt =>
 esteira.addEventListener(evt, () => {
 setTimeout(() => {
 userIsInteracting = false;
 startAutoScroll();
 }, 3000);
 })
 );
</script>
